import os
import string
import unicodedata

from robot.libraries.BuiltIn import BuiltIn


# TODO: Refactor Testpath methods to not use BuiltIn and get rid of robotframework dependency
class Testpath:
    """This class provides methods for getting test hierarchy structure of currently executed test case in various forms."""

    def get_test_hierarchy(self) -> list:
        """Return list containing test hierarchy structure of currently executed test.

        :return: Current test hierarchy based on test phase.
        :rtype: list
        """
        robot_builtin_keywords = BuiltIn()

        current_test_suite_name = robot_builtin_keywords.get_variable_value(
            "${SUITE_NAME}"
        )
        current_test_case_name = robot_builtin_keywords.get_variable_value(
            "${TEST_NAME}"
        )

        current_test_hierarchy = current_test_suite_name.split(".")
        if current_test_case_name is not None:
            current_test_hierarchy.append(current_test_case_name)

        current_test_hierarchy = [
            self._convert_string(test_hier_item)
            for test_hier_item in current_test_hierarchy
        ]
        return current_test_hierarchy

    def get_test_path(self) -> str:
        """Return log folder path for current test built from test hierarchy structure of currently executed test case.

        :return: Unified test path calculed from ${OUTPUT} variable available during test execution.
        :rtype: string
        """
        robot_builtin_keywords = BuiltIn()
        root_log_folder_path = robot_builtin_keywords.get_variable_value(
            "${OUTPUT_DIR}"
        )

        current_test_hierarchy = self.get_test_hierarchy()
        current_test_hierarchy_path = os.path.join(*current_test_hierarchy)

        current_test_log_folder_path = os.path.join(
            root_log_folder_path, current_test_hierarchy_path
        )
        current_test_log_folder_path = os.path.normpath(current_test_log_folder_path)

        return current_test_log_folder_path

    def _convert_string(self, value: str) -> str:
        """Normalizes string, removes characters that are not allowed in file names."""
        value = unicodedata.normalize("NFKD", str(value)).encode("ascii", "ignore")
        valid_chars = "-_.() %s%s" % (string.ascii_letters, string.digits)
        return "".join(chr(c) for c in value if chr(c) in valid_chars)
